"""Generate the sole Go public binding from contracts/openapi.json (stdlib only).
Run --check for zero-write Go-token drift detection (gofmt-insensitive). No Go invocation required.
"""
from __future__ import annotations
import argparse
import hashlib
import json
from pathlib import Path
import re
import sys

ROOT = Path(__file__).resolve().parents[2]
SOURCE = ROOT / 'contracts/openapi.json'
TARGET = ROOT / 'internal/protocol/openapi_generated.go'


def name(value):
    parts = re.findall(r'[A-Za-z0-9]+', value)
    return ''.join(p[:1].upper() + p[1:] for p in parts)


def generate(raw):
    doc = json.loads(raw.decode('utf-8'))
    schemas = doc['components']['schemas']
    allowed = {'type', '$ref', 'description', 'pattern', 'minLength', 'maxLength',
               'not', 'const', 'enum', 'properties', 'required', 'additionalProperties',
               'items', 'allOf', 'anyOf', 'if', 'then', 'else', 'format', 'minimum', 'maximum',
               'default', 'x-maximum-decimal', 'x-unicode-scalar-count',
               'x-no-normalization', 'x-max-utf8-bytes'}
    def supported(s):
        unknown = set(s) - allowed
        if unknown:
            raise ValueError(f'unsupported schema keywords: {unknown}')
        for k in ('not', 'items', 'if', 'then', 'else'):
            if k in s:
                supported(s[k])
        for k in ('allOf', 'anyOf'):
            for v in s.get(k, []):
                supported(v)
        for v in s.get('properties', {}).values():
            supported(v)
        if '$ref' in s and s['$ref'].removeprefix('#/components/schemas/') not in schemas:
            raise ValueError('non-component reference')
        if s.get('type') == 'object' and s.get('additionalProperties') is not False:
            raise ValueError('all public objects must reject unknown properties')
    for s in schemas.values():
        supported(s)
    out = ['// Code generated by tests/fixtures/generate_protocol.py; DO NOT EDIT.',
           '// Source: contracts/openapi.json. Runtime validation uses this same generated schema.',
           'package protocol', '',
           'const OpenAPISHA256 = ' + json.dumps(hashlib.sha256(raw).hexdigest()),
           'const RequestMaxBytes = ' + str(doc['x-transport-policy']['requestMaxBytes']), '']
    enums = {}
    def gotype(s, hint):
        if '$ref' in s:
            return s['$ref'].split('/')[-1]
        if s.get('type') == 'string' and ('enum' in s or 'const' in s):
            enums[hint] = s.get('enum', [s.get('const')])
            return hint
        return {'string': 'string', 'integer': 'int64', 'boolean': 'bool',
                'array': '[]' + gotype(s['items'], hint + 'Item') if s.get('type') == 'array' else ''}.get(s.get('type')) or fail(s)
    def fail(s):
        raise ValueError(f'unsupported DTO: {s}')
    for n, s in schemas.items():
        if s.get('type') == 'object':
            out += ['type ' + n + ' struct {']
            for p, ps in s['properties'].items():
                typ = gotype(ps, n + name(p))
                optional = p not in s['required']
                tag = p + (',omitempty' if optional else '')
                out += ['    ' + name(p) + ' ' + ('*' if optional else '') + typ + ' `json:' + json.dumps(tag) + '`']
            out += ['}', '']
        else:
            typ = 'string' if '$ref' in s else gotype(s, n)
            if typ == n:
                typ = 'string'
            out += ['type ' + n + ' ' + typ, '']
    for n, vals in enums.items():
        if n not in schemas:
            out += ['type ' + n + ' string', '']
        out += ['const (']
        for v in vals:
            out += ['    ' + n + name(v) + ' ' + n + ' = ' + json.dumps(v)]
        out += [')', '']
    for n in schemas:
        out += [f'func (v {n}) MarshalJSON() ([]byte, error) {{', f'    type plain {n}',
                f'    return marshalValidated("{n}", plain(v))', '}', '']
        out += [f'func (v *{n}) UnmarshalJSON(data []byte) error {{',
                f'    type plain {n}', '    var next plain',
                f'    if err := unmarshalValidated("{n}", data, &next); err != nil {{ return err }}',
                f'    *v = {n}(next)', '    return nil', '}', '']
    # Inline enum types are also validated independently when used directly.
    inline = {n: v for n, v in enums.items() if n not in schemas}
    for n in inline:
        out += [f'func (v {n}) MarshalJSON() ([]byte, error) {{', f'    return marshalValidated("{n}", string(v))', '}', '']
        out += [f'func (v *{n}) UnmarshalJSON(data []byte) error {{',
                '    var next string', f'    if err := unmarshalValidated("{n}", data, &next); err != nil {{ return err }}',
                f'    *v = {n}(next)', '    return nil', '}', '']
    full = dict(schemas)
    full.update({n: {'type': 'string', 'enum': vals} for n, vals in inline.items()})
    out += ['const schemaJSON = ' + json.dumps(json.dumps(full, ensure_ascii=True, separators=(',', ':'))), '']
    operations = []
    for path, methods in doc['paths'].items():
        for method, op in methods.items():
            ops = {'id': op['operationId'], 'method': method.upper(), 'path': path,
                   'action': op['x-required-action'], 'body': '', 'parameters': op.get('parameters', [])}
            if 'requestBody' in op:
                ops['body'] = op['requestBody']['content']['application/json']['schema']['$ref'].split('/')[-1]
            for p in ops['parameters']:
                supported(p['schema'])
            operations.append(ops)
    out += ['const operationJSON = ' + json.dumps(json.dumps(operations, ensure_ascii=True, separators=(',', ':'))), '']
    return ('\n'.join(out)).encode('utf-8')


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--check', action='store_true')
    args = ap.parse_args()
    result = generate(SOURCE.read_bytes())
    if args.check:
        # Preserve string/raw-string/comment contents; ignore only whitespace
        # between Go lexical tokens so gofmt cannot create false drift.
        def tokens(b):
            return re.findall(r'"(?:\\.|[^"\\])*"|`[^`]*`|//[^\r\n]*|[A-Za-z0-9_]+|[^\s]', b.decode('utf-8'))
        if not TARGET.exists() or tokens(TARGET.read_bytes()) != tokens(result):
            raise ValueError('generated protocol drift; run python -B tests/fixtures/generate_protocol.py')
        print('protocol generation drift check passed')
    else:
        TARGET.parent.mkdir(parents=True, exist_ok=True)
        TARGET.write_bytes(result)
        print('generated internal/protocol/openapi_generated.go')


if __name__ == '__main__':
    try:
        main()
    except (ValueError, KeyError, TypeError) as e:
        print(f'protocol generation failed: {e}', file=sys.stderr)
        raise SystemExit(1)
